const s = wb.getWorksheet('Sheet1');
for (let r = 3; r <= 36; r++) s.getRange('A'+r).setValue(`=IF(B${r}="","",$B$2&"-02-"&TEXT(9+COUNTA($B$3:B${r}),"000"))`);
const a = s.getRange('A3:A36').getValues().map(x=>x[0]);
const e = s.getRange('E3:E36').getValues().map(x=>x[0]);
const b = s.getRange('B3:B36').getValues().map(x=>x[0]);
log(a.map((v,i)=>`${i+3}: ${JSON.stringify(b[i])} -> ${JSON.stringify(v)}`).join('\n'));
log('mismatch vs E sample', a.map((v,i)=>e[i]!=null&&e[i]!==''&&e[i]!==v? i+3:null).filter(x=>x));
log('A3', s.getRange('A3').getCell().getFormula?.(), 'A36', s.getRange('A36').getCell().getFormula?.());
log('blanks with B nonblank', a.filter((v,i)=>(v===''||v==null)&&b[i]!=null&&b[i]!=='').length, 'distinct', new Set(a.filter(v=>v)).size);
log(wb.getRange('Sheet1!A3:A36').getCounts());

